using Amifolio.Core;

internal static class CollectionCases
{
    internal static (string,Func<Fixture,Task>)[] All =>
    [
        ("collection metadata edits retain distinct same-name file lineages",async f=>{var a=f.File("project/out/a/report.md","one");var b=f.File("project/out/b/report.md","two");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var s=new CollectionService((PortfolioStore)f.Store);await s.GrantAsync(project.Id,Path.Combine(f.Root,"project/out"),true);var first=await s.ReconcileAsync(Path.Combine(f.Root,"project"));foreach(var row in await f.Store.ListAsync())await f.Store.UpdateArtifactAsync(row.Id,"renamed","tag",project.Id);await File.WriteAllTextAsync(a,"two");var next=await s.ReconcileAsync(Path.Combine(f.Root,"project"));Check(next.Single().ArtifactId!=first.Single(x=>x.Path==Path.GetFullPath(b)).ArtifactId);Check((await f.Store.ListAsync()).Count==3);}),
        ("collection selecting source directory as root stays excluded",async f=>{var file=f.File("project/references/notes.md","source");var s=new CollectionService((PortfolioStore)f.Store);await Reject(()=>s.PreviewAsync(Path.GetDirectoryName(file)!));Check((await f.Store.ListAsync()).Count==0);}),
        ("collection truncated scope creates visible incomplete receipt",async f=>{var root=Path.Combine(f.Root,"outputs");Directory.CreateDirectory(root);var s=new CollectionService((PortfolioStore)f.Store);var preview=new CollectionPreview(root,null,"用户",[],true);var rows=await s.CollectAsync(preview);Check(rows.Single().State=="incomplete");}),
        ("collection explicit Codex submit and hook share lineage and receipts",async f=>{var p=f.File("project/out/a.md","one");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var s=new CollectionService((PortfolioStore)f.Store);await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,true);var submitted=await f.Store.ImportFileAsync(p,project.Id,"Codex");Check((await s.ReconcileAsync(Path.Combine(f.Root,"project"))).Count==0);await File.WriteAllTextAsync(p,"two");var collected=(await s.ReconcileAsync(Path.Combine(f.Root,"project"))).Single();var same=await f.Store.ImportFileAsync(p,project.Id,"Codex");Check(same.Artifact.Id==collected.ArtifactId&&same.Artifact.Version==2&&(await f.Store.ListAsync()).Count==2);}),
        ("collection revoked grant cannot complete a stale batch",async f=>{var p=f.File("project/out/a.md","one");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var store=(PortfolioStore)f.Store;var s=new CollectionService(store);await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,true);var grant=(await s.GrantsAsync()).Single();var preview=await s.PreviewAsync(Path.GetDirectoryName(p)!,project.Id,"Codex");var id=await store.StartCollectionAsync(preview,null,grant,CancellationToken.None);await s.GrantAsync(project.Id,grant.Root,false);await Reject(()=>store.ImportCollectedAsync(preview.Entries.Single(),project.Id,"Codex",new(id,p,preview.Entries.Single().Hash,project.Id,grant.Revision),CancellationToken.None));Check((await store.ListAsync()).Count==0);}),
        ("collection interrupted batch is visible after next finite reconciliation",async f=>{var p=f.File("outputs/a.md","one");var store=(PortfolioStore)f.Store;var s=new CollectionService(store);var preview=await s.PreviewAsync(Path.GetDirectoryName(p)!);await store.StartCollectionAsync(preview,null,null,CancellationToken.None);await s.CollectAsync(preview);var rows=await s.ListReceiptsAsync();Check(rows.Any(r=>r.State=="interrupted")&&rows.Any(r=>r.State=="archived"));}),
        ("collection preview is read-only and excludes secrets links caches",async f=>{var p=f.File("outputs/report.md","one");f.File("outputs/.env","secret");f.File("outputs/bin/build.txt","cache");var service=new CollectionService((PortfolioStore)f.Store);var preview=await service.PreviewAsync(Path.GetDirectoryName(p)!);Check(preview.Entries.Count(x=>x.State=="ready")==1);Check((await f.Store.ListAsync()).Count==0);Check(preview.Entries.Count(x=>x.State=="excluded")==2);}),
        ("collection commits durable receipt and no duplicate versions",async f=>{var p=f.File("outputs/report.md","one");var service=new CollectionService((PortfolioStore)f.Store);var preview=await service.PreviewAsync(Path.GetDirectoryName(p)!);var a=await service.CollectAsync(preview);var b=await service.CollectAsync(preview);Check(a.Single().State=="archived"&&b.Single().ArtifactId==a[0].ArtifactId);Check((await f.Restart().ListAsync()).Count==1);Check((await service.ListReceiptsAsync()).Count==2);}),
        ("collection rejects changed files after preview",async f=>{var p=f.File("outputs/report.md","one");var s=new CollectionService((PortfolioStore)f.Store);var preview=await s.PreviewAsync(Path.GetDirectoryName(p)!);await File.WriteAllTextAsync(p,"two");var results=await s.CollectAsync(preview);Check(results.Single().State=="changed"&&(await f.Store.ListAsync()).Count==0);}),
        ("collection same filenames in different folders have separate lineage",async f=>{var p=f.File("outputs/a/report.md","one");f.File("outputs/b/report.md","two");var s=new CollectionService((PortfolioStore)f.Store);await s.CollectAsync(await s.PreviewAsync(Path.Combine(f.Root,"outputs")));var records=await f.Store.ListAsync();Check(records.Count==2&&records.All(a=>a.Version==1));await File.WriteAllTextAsync(p,"three");await s.CollectAsync(await s.PreviewAsync(Path.Combine(f.Root,"outputs")));Check((await f.Store.ListAsync()).Count==3);}),
        ("collection unselected rows visible and no archive",async f=>{var p=f.File("outputs/a.md","one");f.File("outputs/b.md","two");var s=new CollectionService((PortfolioStore)f.Store);var preview=await s.PreviewAsync(Path.GetDirectoryName(p)!);var result=await s.CollectAsync(preview,[p]);Check(result.Count(x=>x.State=="unsubmitted")==1&&result.Count(x=>x.State=="archived")==1);}),
        ("collection automatic scope must be project output subdirectory",async f=>{var p=f.File("project/out/a.md","one");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var s=new CollectionService((PortfolioStore)f.Store);await Reject(()=>s.GrantAsync(project.Id,Path.Combine(f.Root,"project"),true));await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,true);var result=await s.ReconcileAsync(Path.Combine(f.Root,"project"));Check(result.Single().State=="archived"&&(await f.Store.ListAsync()).Single().ProjectId==project.Id);Check((await s.ReconcileAsync(Path.Combine(f.Root,"project"))).Count==0);}),
        ("collection disabled scopes do not scan or restore deleted outputs",async f=>{var p=f.File("project/out/a.md","one");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var s=new CollectionService((PortfolioStore)f.Store);await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,true);var result=await s.ReconcileAsync(Path.Combine(f.Root,"project"));await f.Store.RemoveArtifactAsync(result[0].ArtifactId!);Check((await s.ReconcileAsync(Path.Combine(f.Root,"project"))).Count==0);await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,false);await File.WriteAllTextAsync(p,"new");Check((await s.ReconcileAsync(Path.Combine(f.Root,"project"))).Count==0);}),
        ("collection backup restore disables automatic authorization",async f=>{var p=f.File("project/out/a.md","one");var project=await f.Store.CreateProjectAsync("p",Path.Combine(f.Root,"project"));var s=new CollectionService((PortfolioStore)f.Store);await s.GrantAsync(project.Id,Path.GetDirectoryName(p)!,true);var backup=Path.Combine(f.Root,"backup.zip");await new PortfolioMaintenance(f.DataRoot).BackupAsync(backup);await new PortfolioMaintenance(f.DataRoot).RestoreAsync(backup);Check((await new CollectionService((PortfolioStore)f.Restart()).GrantsAsync()).All(x=>!x.Enabled));}),
        ("collection cancellation leaves explicit receipts and original files",async f=>{var p=f.File("outputs/a.md","one");var s=new CollectionService((PortfolioStore)f.Store);var preview=await s.PreviewAsync(Path.GetDirectoryName(p)!);using var c=new CancellationTokenSource();c.Cancel();try{await s.CollectAsync(preview,null,c.Token);}catch(OperationCanceledException){}Check(File.Exists(p)&&(await f.Store.ListAsync()).Count==0);})
    ];
    private static void Check(bool b){if(!b)throw new Exception("collection invariant failed");}
    private static async Task Reject(Func<Task> action){try{await action();}catch(IOException){return;}throw new Exception("expected rejected scope");}
}
